#include "tgcloud/transfer/queue.hpp"
namespace tgcloud::transfer { TransferQueue::TransferQueue(size_t n){if(!n)n=1;while(n--)workers_.emplace_back(&TransferQueue::run,this);} void TransferQueue::run(){for(;;){std::function<void()>j;{std::unique_lock l(m_);cv_.wait(l,[&]{return stop_||!q_.empty();});if(stop_&&q_.empty())return;j=std::move(q_.front());q_.pop();}j();}} void TransferQueue::submit(std::function<void()>j){{std::lock_guard l(m_);if(stop_)return;q_.push(std::move(j));}cv_.notify_one();} TransferQueue::~TransferQueue(){{std::lock_guard l(m_);stop_=true;}cv_.notify_all();for(auto&t:workers_)t.join();} }
